import hashlib,json,os
from datetime import date,timedelta
from pathlib import Path
import pymssql
from fastapi import FastAPI
from fastapi.testclient import TestClient
from core.security import create_token
from modules.catalogo_ampliado.routes import router
OUT=Path(os.environ['GATE6_EVIDENCE_FILE']); MARK='G6E2E-'+os.environ['GITHUB_RUN_ID']
def conn(): return pymssql.connect(server=os.environ['EDARSAHUB_SQL_HOST'],port=int(os.environ['EDARSAHUB_SQL_PORT']),database=os.environ['EDARSAHUB_SQL_DATABASE'],user=os.environ['EDARSAHUB_SQL_USER'],password=os.environ['EDARSAHUB_SQL_PASSWORD'])
def req(c,m,p,t=None,b=None): return c.request(m,p,headers={'Authorization':'Bearer '+t} if t else {},json=b)
def main():
 e={'status':'FAIL','checks':{},'production_touched':False}; ids={k:None for k in ('tipo','persona','vinculo','doc','ver','alerta')}; db=conn(); q=db.cursor(as_dict=True); cfg=None; emp=None
 try:
  q.execute("SELECT TOP 1 uc.UsuarioID,uc.Email,ur.NombreRol FROM dbo.Usuario_Catalogo uc JOIN dbo.Usuario_RolesAsignacion a ON a.UsuarioID=uc.UsuarioID AND ISNULL(a.Activo,1)=1 JOIN dbo.Usuario_Roles ur ON ur.RolID=a.RolID AND ISNULL(ur.Activo,1)=1 WHERE ISNULL(uc.Activo,1)=1 AND ur.NivelJerarquia>=80 AND uc.Email IS NOT NULL ORDER BY ur.NivelJerarquia DESC"); full=q.fetchone()
  q.execute("SELECT TOP 1 uc.UsuarioID,uc.Email,ur.NombreRol FROM dbo.Usuario_Catalogo uc JOIN dbo.Usuario_RolesAsignacion a ON a.UsuarioID=uc.UsuarioID AND ISNULL(a.Activo,1)=1 JOIN dbo.Usuario_Roles ur ON ur.RolID=a.RolID AND ISNULL(ur.Activo,1)=1 WHERE ISNULL(uc.Activo,1)=1 AND ur.NivelJerarquia<80 AND uc.Email IS NOT NULL ORDER BY ur.NivelJerarquia"); low=q.fetchone()
  q.execute("SELECT TOP 1 u.UsuarioID FROM dbo.Usuario_Catalogo u LEFT JOIN dbo.Gobierno_PersonaVinculo v ON v.UsuarioID=u.UsuarioID WHERE ISNULL(u.Activo,1)=1 AND v.VinculoID IS NULL ORDER BY u.UsuarioID"); link=q.fetchone(); q.execute("SELECT TOP 1 EmpresaID FROM dbo.Sistema_Empresas ORDER BY EmpresaID"); er=q.fetchone()
  if not all((full,low,link,er)): raise RuntimeError('CANONICAL_FIXTURE_MISSING')
  emp=int(er['EmpresaID']); q.execute("SELECT * FROM dbo.Gobierno_EmpresaConfiguracion WHERE EmpresaID=%s",(emp,)); cfg=q.fetchone()
  q.execute("INSERT INTO dbo.Gobierno_TipoDocumento(Codigo,Nombre,PropietarioPermitido,RequiereVigencia,Sensibilidad) OUTPUT INSERTED.TipoDocumentoID VALUES(%s,%s,'EMPRESA',1,'RESTRINGIDO')",(MARK,MARK)); ids['tipo']=int(q.fetchone()['TipoDocumentoID']); db.commit()
  app=FastAPI(); app.include_router(router,prefix='/api'); c=TestClient(app); tf=create_token(str(full['UsuarioID']),full['Email'],full['NombreRol'] or ''); tl=create_token(str(low['UsuarioID']),low['Email'],low['NombreRol'] or '')
  e['checks']['no_auth']=req(c,'GET',f'/api/catalogo-ampliado/empresas/{emp}/configuracion').status_code in (401,403); e['checks']['bad_token']=req(c,'GET',f'/api/catalogo-ampliado/empresas/{emp}/configuracion','bad').status_code==401; e['checks']['rbac_deny']=req(c,'GET',f'/api/catalogo-ampliado/empresas/{emp}/configuracion',tl).status_code==403; e['checks']['rbac_allow']=req(c,'GET',f'/api/catalogo-ampliado/empresas/{emp}/configuracion',tf).status_code==200
  r=req(c,'PUT',f'/api/catalogo-ampliado/empresas/{emp}/configuracion',tf,{'catalogo_legal_ampliado_activo':False,'dias_alerta_default':30}); assert r.status_code==200; e['checks']['inactive_409']=req(c,'GET',f'/api/catalogo-ampliado/empresas/{emp}/documentos',tf).status_code==409; assert req(c,'PUT',f'/api/catalogo-ampliado/empresas/{emp}/configuracion',tf,{'catalogo_legal_ampliado_activo':True,'dias_alerta_default':30}).status_code==200
  r=req(c,'POST','/api/catalogo-ampliado/personas',tf,{'nombre':MARK}); assert r.status_code==201,r.text; ids['persona']=int(r.json()['data']['PersonaID']); r=req(c,'POST',f"/api/catalogo-ampliado/personas/{ids['persona']}/vinculos",tf,{'usuario_id':int(link['UsuarioID']),'cliente_id':None,'proveedor_id':None,'contacto_cliente_id':None,'contacto_proveedor_id':None,'es_principal':True}); assert r.status_code==201,r.text; ids['vinculo']=int(r.json()['data']['VinculoID']); e['checks']['persona_vinculo']=True
  r=req(c,'POST',f'/api/catalogo-ampliado/empresas/{emp}/documentos',tf,{'tipo_documento_id':ids['tipo'],'propietario_tipo':'EMPRESA','titulo':MARK}); assert r.status_code==201,r.text; ids['doc']=int(r.json()['data']['DocumentoID']); today=date.today(); exp=today+timedelta(days=30); sha=hashlib.sha256(MARK.encode()).hexdigest(); r=req(c,'POST',f"/api/catalogo-ampliado/documentos/{ids['doc']}/versiones",tf,{'nombre_archivo':MARK+'.pdf','storage_key':'e2e/'+MARK+'.pdf','mime_type':'application/pdf','tamanio_bytes':123,'sha256':sha,'fecha_emision':str(today),'fecha_vencimiento':str(exp),'fecha_vencimiento_fuente':'CAPTURA'}); assert r.status_code==201,r.text; ids['ver']=int(r.json()['data']['DocumentoVersionID'])
  k=req(c,'GET',f"/api/catalogo-ampliado/documentos/{ids['doc']}/kardex",tf); assert k.status_code==200; kinds={x['TipoMovimiento'] for x in k.json()['data']}; e['checks']['kardex']={'CREACION','NUEVA_VERSION'}<=kinds
  q.execute("UPDATE dbo.Gobierno_DocumentoVersion SET EstadoRevision='VALIDADO',RevisadoPorUsuarioID=%s,FechaRevision=SYSUTCDATETIME() WHERE DocumentoVersionID=%s",(full['UsuarioID'],ids['ver'])); db.commit(); d=req(c,'GET',f'/api/catalogo-ampliado/empresas/{emp}/vencimientos?dias=60',tf); assert d.status_code==200; e['checks']['vencimiento']=any(int(x['DocumentoVersionID'])==ids['ver'] for x in d.json()['data'])
  r=req(c,'POST',f'/api/catalogo-ampliado/empresas/{emp}/alertas/reglas',tf,{'tipo_documento_id':ids['tipo'],'usuario_objetivo_id':int(full['UsuarioID']),'dias_antes':30,'canal':'APP'}); assert r.status_code==201,r.text; ids['alerta']=int(r.json()['data']['AlertaReglaID']); a=req(c,'GET',f'/api/catalogo-ampliado/empresas/{emp}/alertas/reglas',tf); assert a.status_code==200; e['checks']['alerta']=any(int(x['AlertaReglaID'])==ids['alerta'] for x in a.json()['data']); assert all(e['checks'].values()); e['status']='PASS'
 except Exception as x: e['error']=type(x).__name__+': '+str(x)[:400]
 finally:
  try:
   if ids['alerta']: q.execute("DELETE FROM dbo.Gobierno_AlertaRegla WHERE AlertaReglaID=%s",(ids['alerta'],))
   if ids['doc']: q.execute("DELETE FROM dbo.Gobierno_DocumentoMovimiento WHERE DocumentoID=%s",(ids['doc'],)); q.execute("DELETE FROM dbo.Gobierno_DocumentoVersion WHERE DocumentoID=%s",(ids['doc'],)); q.execute("DELETE FROM dbo.Gobierno_Documento WHERE DocumentoID=%s",(ids['doc'],))
   if ids['vinculo']: q.execute("DELETE FROM dbo.Gobierno_PersonaVinculo WHERE VinculoID=%s",(ids['vinculo'],))
   if ids['persona']: q.execute("DELETE FROM dbo.Gobierno_Persona WHERE PersonaID=%s",(ids['persona'],))
   if ids['tipo']: q.execute("DELETE FROM dbo.Gobierno_TipoDocumento WHERE TipoDocumentoID=%s",(ids['tipo'],))
   if emp is not None:
    if cfg: q.execute("UPDATE dbo.Gobierno_EmpresaConfiguracion SET CatalogoLegalAmpliadoActivo=%s,DiasAlertaDefault=%s,Activo=%s,UsuarioActualizacionID=%s WHERE EmpresaID=%s",(cfg['CatalogoLegalAmpliadoActivo'],cfg['DiasAlertaDefault'],cfg['Activo'],cfg['UsuarioActualizacionID'],emp))
    else: q.execute("DELETE FROM dbo.Gobierno_EmpresaConfiguracion WHERE EmpresaID=%s",(emp,))
   db.commit(); q.execute("SELECT COUNT_BIG(*) n FROM dbo.Gobierno_Persona WHERE Nombre=%s",(MARK,)); e['cleanup']={'complete':True,'residue':int(q.fetchone()['n'])}; e['status']='FAIL' if e['cleanup']['residue'] else e['status']
  except Exception as cx: db.rollback(); e['cleanup']={'complete':False,'error':str(cx)[:300]}; e['status']='FAIL'
  q.close(); db.close(); OUT.parent.mkdir(parents=True,exist_ok=True); OUT.write_text(json.dumps(e,indent=2,sort_keys=True),encoding='utf-8')
 if e['status']!='PASS': raise SystemExit(e.get('error','E2E_FAILED'))
if __name__=='__main__': main()
